# Helper to instantiate and run statsplot2Class from the current test environment
sp2_run <- function(data, dep = NULL, group = NULL, grvar = NULL, subjectID = NULL,
                    direction = "independent", distribution = "p", forceContinuous = FALSE,
                    alluvsty = "t1", showSummary = FALSE, showExplanations = FALSE,
                    excl = FALSE, sampleLarge = FALSE, sampleThreshold = 10000,
                    sampleSize = 5000, seed = 42, originaltheme = FALSE) {
  opts_cls <- get("statsplot2Options", inherits = TRUE)
  anl_cls  <- get("statsplot2Class", inherits = TRUE)
  opts <- opts_cls$new(
    dep = dep, group = group, grvar = grvar, subjectID = subjectID,
    direction = direction, distribution = distribution, forceContinuous = forceContinuous,
    alluvsty = alluvsty, showSummary = showSummary, showExplanations = showExplanations,
    excl = excl, sampleLarge = sampleLarge, sampleThreshold = sampleThreshold,
    sampleSize = sampleSize, seed = seed, originaltheme = originaltheme
  )
  a <- anl_cls$new(options = opts, data = data)
  suppressWarnings(suppressMessages(a$run()))
  priv <- a$.__enclos_env__$private
  st <- priv$.extractStats(priv$.cached_plot)
  list(
    analysis = a,
    results  = a$results,
    private  = priv,
    plot     = priv$.cached_plot,
    stats    = st,
    sd       = if (length(st) >= 1L) st[[1]]$sd else NULL,
    notices  = paste(as.character(a$results$notices$content), collapse = "\n"),
    summary  = paste(as.character(a$results$summary$content), collapse = "\n"),
    explain  = paste(as.character(a$results$ExplanationMessage$content), collapse = "\n"),
    todo     = paste(as.character(a$results$todo$content), collapse = "\n")
  )
}

sp2_strip_html <- function(x) {
  x <- gsub("</?[a-zA-Z][^>]*>", " ", paste(as.character(x), collapse = " "))
  trimws(gsub("[[:space:]]+", " ", x))
}

# Deterministic tiny fixtures (hand-checkable, n <= 18; non-integer values so
# .infer_type() classifies them as continuous without needing forceContinuous = TRUE)
d_tiny_2g <- data.frame(
  y = c(10.1, 12.1, 12.1, 14.1, 16.1, 18.1,
        20.1, 22.1, 24.1, 24.1, 28.1, 30.1, NA_real_),
  g = factor(c(rep("Ctrl", 6), rep("Drug", 6), "Ctrl"), levels = c("Ctrl", "Drug"))
)

d_tiny_3g <- data.frame(
  y   = c(10.1, 11.1, 12.1, 13.1,
          15.1, 17.1, 18.1, 20.1,
          22.1, 25.1, 27.1, 30.1),
  grp = factor(rep(c("G1", "G2", "G3"), each = 4), levels = c("G1", "G2", "G3"))
)

y_pre  <- c(10.1, 14.1, 15.1, 18.1, 21.1, 25.1)
y_post <- c(13.1, 18.1, 17.1, 23.1, 27.1, 30.1)
d_tiny_pair2 <- data.frame(
  id   = factor(c(paste0("S", 1:6), paste0("S", 1:6), "S7")),
  time = factor(c(rep("Pre", 6), rep("Post", 6), "Pre"), levels = c("Pre", "Post")),
  y    = c(y_pre, y_post, 99.1)
)

mat_rm3 <- cbind(
  V1 = c(10.1, 15.1, 15.1, 18.1, 20.1, 25.1),
  V2 = c(12.1, 12.1, 19.1, 20.1, 24.1, 27.1),
  V3 = c(18.1, 20.1, 22.1, 26.1, 29.1, 35.1)
)
d_tiny_rm3 <- data.frame(
  id    = factor(rep(paste0("P", 1:6), times = 3)),
  visit = factor(rep(c("V1", "V2", "V3"), each = 6), levels = c("V1", "V2", "V3")),
  y     = as.numeric(mat_rm3)
