d_tiny_cc <- data.frame(
  x = c(1.1, 2.3, 3.2, 4.5, 5.1, 6.4, 7.2, 8.6, 9.1, 10.4),
  y = c(2.5, 5.1, 4.8, 9.2, 8.9, 13.5, 11.8, 17.5, 16.2, 21.0)
)

d_tiny_ff <- data.frame(
  resp = factor(rep(c("Pos", "Pos", "Neg", "Neg"), c(18, 4, 3, 15)), levels = c("Pos", "Neg")),
  arm  = factor(rep(c("Drug", "Ctrl", "Drug", "Ctrl"), c(18, 4, 3, 15)), levels = c("Drug", "Ctrl"))
