# ==============================================================================
# C01-C07: Automatic Type Inference & Plot Family Dispatch
# ==============================================================================

test_that("C01-C06: Automatic dispatch across all six plot families", {
  r1 <- sp2_run(d_tiny_2g, dep = "y", group = "g", direction = "independent")
  expect_equal(r1$private$.detectAnalysisType()$plot_type, "independent_factor_continuous")

  r2 <- sp2_run(d_tiny_cc, dep = "y", group = "x", direction = "independent")
  expect_equal(r2$private$.detectAnalysisType()$plot_type, "independent_continuous_continuous")

  r3 <- sp2_run(d_tiny_ff, dep = "resp", group = "arm", direction = "independent")
  expect_equal(r3$private$.detectAnalysisType()$plot_type, "independent_factor_factor")

  r4 <- sp2_run(d_tiny_2g, dep = "g", group = "y", direction = "independent")
  expect_equal(r4$private$.detectAnalysisType()$plot_type, "independent_continuous_factor")
  expect_equal(r4$sd$statistic, r1$sd$statistic, tolerance = 1e-12)
  expect_equal(r4$sd$estimate,  r1$sd$estimate,  tolerance = 1e-12)

  r5 <- sp2_run(d_tiny_pair2, dep = "y", group = "time", subjectID = "id", direction = "repeated")
  expect_equal(r5$private$.detectAnalysisType()$plot_type, "repeated_factor_continuous")

  r6 <- sp2_run(d_tiny_ff, dep = "resp", group = "arm", direction = "repeated", alluvsty = "t1")
  expect_equal(r6$private$.detectAnalysisType()$plot_type, "repeated_factor_factor")
  tally_df <- as.data.frame(r6$plot$data)
  expect_equal(sum(tally_df$n), 40L)
  expect_equal(tally_df$n[tally_df$gr == "Drug" & tally_df$dp == "Pos"], 18L)
  expect_equal(tally_df$n[tally_df$gr == "Ctrl" & tally_df$dp == "Neg"], 15L)
})

