  d_16int <- data.frame(y = rep(1:16, each = 2), g = factor(rep(c("A", "B"), 16)))

  expect_equal(sp2_run(d_15int, "y", "g", forceContinuous = FALSE)$private$.detectAnalysisType()$dep_type, "factor")
