# ==============================================================================
# C08-C15: Independent-Groups Parametric, Nonparametric, Robust & Bayesian Tests
# ==============================================================================

test_that("C08: Welch two-sample t-test and Hedges' g match closed-form oracle", {
  r <- sp2_run(d_tiny_2g, dep = "y", group = "g", distribution = "p", showSummary = TRUE)
  y1 <- d_tiny_2g$y[1:6]; y2 <- d_tiny_2g$y[7:12]
  se1 <- var(y1) / 6; se2 <- var(y2) / 6
  t_exp  <- (mean(y1) - mean(y2)) / sqrt(se1 + se2)
  df_exp <- (se1 + se2)^2 / (se1^2 / 5 + se2^2 / 5)
  p_exp  <- 2 * pt(-abs(t_exp), df = df_exp)
  J_exp  <- exp(lgamma(df_exp / 2) - 0.5 * log(df_exp / 2) - lgamma((df_exp - 1) / 2))
  g_exp  <- ((mean(y1) - mean(y2)) / sqrt((var(y1) + var(y2)) / 2)) * J_exp

  expect_equal(r$sd$statistic, t_exp,  tolerance = 1e-8)
  expect_equal(r$sd$df.error,  df_exp, tolerance = 1e-8)
  expect_equal(r$sd$p.value,   p_exp,  tolerance = 1e-8)
  expect_equal(r$sd$estimate,  g_exp,  tolerance = 1e-8)
  expect_equal(r$sd$n.obs,     12L)
})

test_that("C08 (VAL-statsplot2-01): Result sentence prints single df without partial-match duplication", {
  r <- sp2_run(d_tiny_2g, dep = "y", group = "g", distribution = "p", showSummary = TRUE)
  sent <- sp2_strip_html(r$summary)
  expect_match(sent, "(df = 9.49)", fixed = TRUE)
})

test_that("C09: Mann-Whitney W and rank-biserial correlation match closed-form oracle", {
  r <- sp2_run(d_tiny_2g, dep = "y", group = "g", distribution = "np")
  # W = 0 (all Ctrl < all Drug), r_rb = 2*(0/36) - 1 = -1
  expect_equal(r$sd$statistic, 0,  tolerance = 1e-8)
  expect_equal(r$sd$estimate, -1,  tolerance = 1e-8)
  expect_equal(r$sd$p.value, suppressWarnings(stats::wilcox.test(d_tiny_2g$y[1:6], d_tiny_2g$y[7:12], exact = FALSE, correct = TRUE)$p.value), tolerance = 1e-8)
})

test_that("C10: Yuen's 20% trimmed-means test matches closed-form trimmed/Winsorized oracle", {
  r <- sp2_run(d_tiny_2g, dep = "y", group = "g", distribution = "r", seed = 42)
  # Base-R 20% trimmed means (g = floor(0.2*6) = 1, h = 4):
  wx1 <- c(12.1, 12.1, 12.1, 14.1, 16.1, 16.1)
  wx2 <- c(22.1, 22.1, 24.1, 24.1, 28.1, 28.1)
  d1  <- 5 * var(wx1) / (4 * 3)
  d2  <- 5 * var(wx2) / (4 * 3)
  t_exp  <- abs(mean(d_tiny_2g$y[2:5]) - mean(d_tiny_2g$y[8:11])) / sqrt(d1 + d2)
  df_exp <- (d1 + d2)^2 / (d1^2 / 3 + d2^2 / 3)
  p_exp  <- 2 * pt(-abs(t_exp), df = df_exp)

  expect_equal(r$sd$statistic, t_exp,  tolerance = 1e-8)
  expect_equal(r$sd$df.error,  df_exp, tolerance = 1e-8)
  expect_equal(r$sd$p.value,   p_exp,  tolerance = 1e-8)
})

test_that("C11: Bayesian JZS two-sample BF10 matches 1D numerical quadrature (Rouder et al. 2009)", {
  r <- sp2_run(d_tiny_2g, dep = "y", group = "g", distribution = "bf", seed = 42)
  t_eq <- as.numeric(t.test(d_tiny_2g$y[1:6], d_tiny_2g$y[7:12], var.equal = TRUE)$statistic)
  n_eff <- (6 * 6) / 12; nu <- 10; rscale <- sqrt(2) / 2
  num <- stats::integrate(function(g) {
    (1 + n_eff * g)^(-0.5) * (1 + t_eq^2 / ((1 + n_eff * g) * nu))^(-(nu + 1) / 2) *
      (rscale / sqrt(2 * pi)) * g^(-1.5) * exp(-rscale^2 / (2 * g))
  }, lower = 0, upper = Inf, rel.tol = 1e-10)$value
  bf_exp <- num / ((1 + t_eq^2 / nu)^(-(nu + 1) / 2))
  expect_equal(r$sd$bf10, bf_exp, tolerance = 5e-4)
})

test_that("C11 (VAL-statsplot2-03): Bayesian t-test Result sentence does not mislabel raw mean difference as 'Bayesian t-test ='", {
  r <- sp2_run(d_tiny_2g, dep = "y", group = "g", distribution = "bf", showSummary = TRUE, seed = 42)
  expect_false(grepl("Bayesian t-test = ", sp2_strip_html(r$summary), fixed = TRUE))
})

test_that("C12-C15: Multi-group (k=3) Welch ANOVA, Kruskal-Wallis, Robust t1way, and Bayesian ANOVA", {
  # C12: Welch's ANOVA + omega^2 (using Satterthwaite df2)
  r_p <- sp2_run(d_tiny_3g, dep = "y", group = "grp", distribution = "p")
  ow <- stats::oneway.test(y ~ grp, data = d_tiny_3g, var.equal = FALSE)
  F_exp   <- as.numeric(ow$statistic)
  df1_exp <- as.numeric(ow$parameter[1])
  df2_exp <- as.numeric(ow$parameter[2])
  omega2_exp <- (df1_exp * (F_exp - 1)) / (df1_exp * F_exp + df2_exp + 1)
  expect_equal(r_p$sd$statistic, F_exp,      tolerance = 1e-8)
  expect_equal(r_p$sd$df,        df1_exp,    tolerance = 1e-8)
  expect_equal(r_p$sd$df.error,  df2_exp,    tolerance = 1e-8)
  expect_equal(r_p$sd$p.value,   ow$p.value, tolerance = 1e-8)
  expect_equal(r_p$sd$estimate,  omega2_exp, tolerance = 1e-8)

  # C13: Kruskal-Wallis + epsilon^2
  r_np <- sp2_run(d_tiny_3g, dep = "y", group = "grp", distribution = "np", seed = 42)
  kw <- stats::kruskal.test(y ~ grp, data = d_tiny_3g)
  H_exp <- as.numeric(kw$statistic)
  eps2_exp <- H_exp / ((12^2 - 1) / (12 + 1))
  expect_equal(r_np$sd$statistic, H_exp,    tolerance = 1e-8)
  expect_equal(r_np$sd$df.error,  2,        tolerance = 1e-8)
  expect_equal(r_np$sd$p.value,   kw$p.value, tolerance = 1e-8)
  expect_equal(r_np$sd$estimate,  eps2_exp, tolerance = 1e-8)

  # C14: Robust ANOVA (t1way)
  r_r <- sp2_run(d_tiny_3g, dep = "y", group = "grp", distribution = "r", seed = 42)
  t1 <- WRS2::t1way(y ~ grp, data = d_tiny_3g, tr = 0.2)
  expect_equal(r_r$sd$statistic, as.numeric(t1$test), tolerance = 1e-8)
  expect_equal(r_r$sd$df,        as.numeric(t1$df1),  tolerance = 1e-8)
  expect_equal(r_r$sd$df.error,  as.numeric(t1$df2),  tolerance = 1e-8)
  expect_equal(r_r$sd$p.value,   as.numeric(t1$p.value), tolerance = 1e-8)

  # C15: Bayesian ANOVA BF10
  r_bf <- sp2_run(d_tiny_3g, dep = "y", group = "grp", distribution = "bf", seed = 42)
  bf_exp <- withr::with_seed(42, exp(BayesFactor::anovaBF(y ~ grp, data = d_tiny_3g, rscaleFixed = sqrt(2)/2, progress = FALSE)@bayesFactor$bf[1]))
  expect_equal(r_bf$sd$bf10[1], bf_exp, tolerance = 5e-4)
})

# ==============================================================================
# C16-C23: Repeated-Measures / Within-Subjects Tests (k=2 and k=3)
# ==============================================================================

test_that("C16-C19: Paired k=2 t-test, Wilcoxon signed-rank, Yuen paired, and Bayesian paired JZS", {
  # C16: Paired t-test (incomplete subject S7 automatically dropped -> n = 6 pairs)
  r_p <- sp2_run(d_tiny_pair2, dep = "y", group = "time", subjectID = "id", direction = "repeated", distribution = "p")
  d <- y_pre - y_post
  t_exp <- mean(d) / (sd(d) / sqrt(6))
  J_5   <- exp(lgamma(5 / 2) - 0.5 * log(5 / 2) - lgamma(4 / 2))
  gz_exp <- (mean(d) / sd(d)) * J_5
  expect_equal(r_p$sd$statistic, t_exp, tolerance = 1e-8)
  expect_equal(r_p$sd$df.error,  5,     tolerance = 1e-8)
  expect_equal(r_p$sd$p.value,   2 * pt(-abs(t_exp), df = 5), tolerance = 1e-8)
  expect_equal(r_p$sd$estimate,  gz_exp, tolerance = 1e-8)
  expect_equal(r_p$sd$n.obs,     6L)

  # C17: Wilcoxon signed-rank V & matched-pairs rank-biserial
  r_np <- sp2_run(d_tiny_pair2, dep = "y", group = "time", subjectID = "id", direction = "repeated", distribution = "np")
  expect_equal(r_np$sd$statistic, 0,  tolerance = 1e-8)
  expect_equal(r_np$sd$estimate, -1,  tolerance = 1e-8)

  # C18: Paired Yuen's test
  r_r <- sp2_run(d_tiny_pair2, dep = "y", group = "time", subjectID = "id", direction = "repeated", distribution = "r", seed = 42)
  yd <- WRS2::yuend(y_pre, y_post, tr = 0.2)
  expect_equal(r_r$sd$statistic, as.numeric(yd$test),    tolerance = 1e-8)
  expect_equal(r_r$sd$df.error,  as.numeric(yd$df),      tolerance = 1e-8)
  expect_equal(r_r$sd$p.value,   as.numeric(yd$p.value), tolerance = 1e-8)

  # C19: Paired JZS BF10 against 1D numerical quadrature
  r_bf <- sp2_run(d_tiny_pair2, dep = "y", group = "time", subjectID = "id", direction = "repeated", distribution = "bf", seed = 42)
  nu <- 5; rscale <- sqrt(2) / 2
  num <- stats::integrate(function(g) {
    (1 + 6 * g)^(-0.5) * (1 + t_exp^2 / ((1 + 6 * g) * nu))^(-(nu + 1) / 2) *
      (rscale / sqrt(2 * pi)) * g^(-1.5) * exp(-rscale^2 / (2 * g))
  }, lower = 0, upper = Inf, rel.tol = 1e-10)$value
  bf_exp <- num / ((1 + t_exp^2 / nu)^(-(nu + 1) / 2))
  expect_equal(r_bf$sd$bf10, bf_exp, tolerance = 5e-4)
})

test_that("C20-C23: Repeated-measures k=3 RM-ANOVA (Greenhouse-Geisser), Friedman, Robust rmanova, Bayesian RM-ANOVA", {
  # C20: RM-ANOVA with Greenhouse-Geisser correction
  r_p <- sp2_run(d_tiny_rm3, dep = "y", group = "visit", subjectID = "id", direction = "repeated", distribution = "p")
  n <- nrow(mat_rm3); k <- ncol(mat_rm3)
  SS_cond <- n * sum((colMeans(mat_rm3) - mean(mat_rm3))^2)
  SS_subj <- k * sum((rowMeans(mat_rm3) - mean(mat_rm3))^2)
  SS_err  <- sum((mat_rm3 - mean(mat_rm3))^2) - SS_cond - SS_subj
  F_exp   <- (SS_cond / (k - 1)) / (SS_err / ((n - 1) * (k - 1)))
  S_dc    <- (diag(k) - 1/k) %*% cov(mat_rm3) %*% (diag(k) - 1/k)
  eps_gg  <- (sum(diag(S_dc))^2) / ((k - 1) * sum(S_dc^2))
  expect_equal(r_p$sd$statistic, F_exp,                 tolerance = 1e-8)
  expect_equal(r_p$sd$df,        eps_gg * (k - 1),      tolerance = 1e-8)
  expect_equal(r_p$sd$df.error,  eps_gg * (n - 1)*(k-1), tolerance = 1e-8)
  expect_equal(r_p$sd$p.value,   pf(F_exp, eps_gg*(k-1), eps_gg*(n-1)*(k-1), lower.tail = FALSE), tolerance = 1e-8)

  # C21: Friedman + Kendall's W
  r_np <- sp2_run(d_tiny_rm3, dep = "y", group = "visit", subjectID = "id", direction = "repeated", distribution = "np", seed = 42)
  fr <- stats::friedman.test(mat_rm3)
  Q_exp <- as.numeric(fr$statistic)
  expect_equal(r_np$sd$statistic, Q_exp,             tolerance = 1e-8)
  expect_equal(r_np$sd$df.error,  2,                 tolerance = 1e-8)
  expect_equal(r_np$sd$p.value,   fr$p.value,        tolerance = 1e-8)
  expect_equal(r_np$sd$estimate,  Q_exp / (6 * 2),   tolerance = 1e-8)

  # C22: Robust RM-ANOVA
  r_r <- sp2_run(d_tiny_rm3, dep = "y", group = "visit", subjectID = "id", direction = "repeated", distribution = "r", seed = 42)
  rm_wrs <- WRS2::rmanova(d_tiny_rm3$y, d_tiny_rm3$visit, d_tiny_rm3$id, tr = 0.2)
  expect_equal(r_r$sd$statistic, as.numeric(rm_wrs$test),    tolerance = 1e-8)
  expect_equal(r_r$sd$df,        as.numeric(rm_wrs$df1),     tolerance = 1e-8)
  expect_equal(r_r$sd$df.error,  as.numeric(rm_wrs$df2),     tolerance = 1e-8)
  expect_equal(r_r$sd$p.value,   as.numeric(rm_wrs$p.value), tolerance = 1e-8)

  # C23: Bayesian RM-ANOVA
  r_bf <- sp2_run(d_tiny_rm3, dep = "y", group = "visit", subjectID = "id", direction = "repeated", distribution = "bf", seed = 42)
  expect_true(is.finite(r_bf$sd$bf10[1]) && r_bf$sd$bf10[1] > 10)
})

# ==============================================================================
# C24-C29: Continuous Association & Contingency Table Tests
# ==============================================================================

test_that("C24-C27: Pearson, Spearman, Winsorized, and Bayesian correlations", {
  # C24: Pearson r + Fisher-z CI
  r_p <- sp2_run(d_tiny_cc, dep = "y", group = "x", distribution = "p")
  ct_p <- stats::cor.test(d_tiny_cc$x, d_tiny_cc$y, method = "pearson")
  expect_equal(r_p$sd$estimate,  as.numeric(ct_p$estimate),  tolerance = 1e-8)
  expect_equal(r_p$sd$statistic, as.numeric(ct_p$statistic), tolerance = 1e-8)
  expect_equal(r_p$sd$df.error,  8,                          tolerance = 1e-8)
  expect_equal(r_p$sd$p.value,   ct_p$p.value,               tolerance = 1e-8)
  expect_equal(r_p$sd$conf.low,  ct_p$conf.int[1],           tolerance = 1e-8)
  expect_equal(r_p$sd$conf.high, ct_p$conf.int[2],           tolerance = 1e-8)

  # C25: Spearman rho & S
  r_np <- sp2_run(d_tiny_cc, dep = "y", group = "x", distribution = "np")
  ct_s <- suppressWarnings(stats::cor.test(d_tiny_cc$x, d_tiny_cc$y, method = "spearman"))
  expect_equal(r_np$sd$estimate,  as.numeric(ct_s$estimate),  tolerance = 1e-8)
  expect_equal(r_np$sd$statistic, as.numeric(ct_s$statistic), tolerance = 1e-8)

  # C26: Winsorized correlation (20% trim, g = floor(0.2*10) = 2)
  r_r <- sp2_run(d_tiny_cc, dep = "y", group = "x", distribution = "r")
  win10 <- function(v) { o <- order(v); s <- v[o]; s[1:2] <- s[3]; s[9:10] <- s[8]; out <- v; out[o] <- s; out }
  rw_exp <- cor(win10(d_tiny_cc$x), win10(d_tiny_cc$y))
  tw_exp <- rw_exp * sqrt(8 / (1 - rw_exp^2))
  expect_equal(r_r$sd$estimate,  rw_exp, tolerance = 1e-8)
  expect_equal(r_r$sd$statistic, tw_exp, tolerance = 1e-8)
  expect_equal(r_r$sd$df.error,  8,      tolerance = 1e-8)

  # C27: Bayesian Pearson correlation
  r_bf <- sp2_run(d_tiny_cc, dep = "y", group = "x", distribution = "bf", seed = 42)
  bf_exp <- withr::with_seed(42, exp(BayesFactor::correlationBF(d_tiny_cc$x, d_tiny_cc$y, rscale = 1/sqrt(2), progress = FALSE)@bayesFactor$bf[1]))
  expect_equal(r_bf$sd$bf10, bf_exp, tolerance = 1e-3)
})

test_that("C28-C29: Contingency table Pearson Chi-square, bias-corrected Cramer's V, and Gunel-Dickey BF10", {
  # C28: Pearson Chi-square (uncorrected) & Bergsma (2013) bias-corrected Cramer's V
  r_p <- sp2_run(d_tiny_ff, dep = "resp", group = "arm", distribution = "p")
  tab <- table(d_tiny_ff$resp, d_tiny_ff$arm)
  csq <- stats::chisq.test(tab, correct = FALSE)
  X2  <- as.numeric(csq$statistic)
  phi2_corr <- max(0, X2 / 40 - 1 / 39)
  rc <- 2 - 1 / 39
  v_exp <- sqrt(phi2_corr / (rc - 1))
  expect_equal(r_p$sd$statistic, X2,          tolerance = 1e-8)
  expect_equal(r_p$sd$df,        1,           tolerance = 0)
  expect_equal(r_p$sd$p.value,   csq$p.value, tolerance = 1e-8)
  expect_equal(r_p$sd$estimate,  v_exp,       tolerance = 1e-8)

  # C29: Gunel-Dickey (1974) closed-form independent multinomial BF10 (fixed row margins, Dirichlet a = 1)
  r_bf <- sp2_run(d_tiny_ff, dep = "resp", group = "arm", distribution = "bf", seed = 42)
  C <- ncol(tab); cs <- colSums(tab); rs <- rowSums(tab); N <- sum(tab)
  log_H1 <- sum(lgamma(C) + rowSums(lgamma(tab + 1)) - lgamma(rs + C))
  log_H0 <- lgamma(C) + sum(lgamma(cs + 1)) - lgamma(N + C)
  expect_equal(r_bf$sd$bf10, exp(log_H1 - log_H0), tolerance = 1e-8)
})

test_that("C29 (VAL-statsplot2-06): Categorical comparison with distribution='bf' does not claim statistical approach is 'not applicable'", {
  r_bf <- sp2_run(d_tiny_ff, dep = "resp", group = "arm", distribution = "bf", showExplanations = TRUE)
  expect_false(grepl("not applicable", r_bf$notices, fixed = TRUE))
  expect_false(grepl("Statistical approach option does not apply to categorical comparisons", r_bf$explain, fixed = TRUE))
})

