test_that("C30: Split-by (grvar) panel statistics match subset analyses exactly", {
  skip_if_not(exists("statsplot2_test"), "statsplot2_test dataset not loaded")
  r_sp <- sp2_run(statsplot2_test, dep = "tumor_reduction", group = "treatment", grvar = "sex", distribution = "p")
  r_f  <- sp2_run(subset(statsplot2_test, sex == "Female"), dep = "tumor_reduction", group = "treatment", distribution = "p")
  r_m  <- sp2_run(subset(statsplot2_test, sex == "Male"),   dep = "tumor_reduction", group = "treatment", distribution = "p")
  lbls <- vapply(r_sp$stats, function(s) as.character(s$label), "")
  expect_equal(r_sp$stats[[which(grepl("Female", lbls))]]$sd$statistic, r_f$sd$statistic, tolerance = 1e-12)
  expect_equal(r_sp$stats[[which(grepl("Male",   lbls))]]$sd$statistic, r_m$sd$statistic, tolerance = 1e-12)
})

