test_that("C31-C32: Missing-value exclusion and large-dataset random subsampling", {
  r_f <- sp2_run(d_tiny_2g, dep = "y", group = "g", excl = FALSE)
  r_t <- sp2_run(d_tiny_2g, dep = "y", group = "g", excl = TRUE)
  expect_equal(r_f$sd$statistic, r_t$sd$statistic, tolerance = 1e-12)
  expect_match(r_f$notices, "1 row(s) carried a missing value", fixed = TRUE)

  set.seed(904)
  d_large <- data.frame(y = rnorm(1500, 50, 10), g = factor(rep(c("A", "B"), 750)))
  r_sub1 <- sp2_run(d_large, dep = "y", group = "g", sampleLarge = TRUE, sampleThreshold = 1000, sampleSize = 400, seed = 42)
  r_sub2 <- sp2_run(d_large, dep = "y", group = "g", sampleLarge = TRUE, sampleThreshold = 1000, sampleSize = 400, seed = 42)
  expect_equal(r_sub1$sd$n.obs, 400L)
  expect_equal(r_sub1$sd$statistic, r_sub2$sd$statistic, tolerance = 1e-12)
  expect_match(r_sub1$notices, "Statistics computed on a random subsample", fixed = TRUE)
})

