      rep(c("Baseline", "Week4", "Week12"), times = 8),
      levels = c("Baseline", "Week4", "Week12")
    ),
    resp = factor(c(
      "PD", "SD", "PR",
      "PD", "PD", "SD",
      "SD", "PR", "CR",
      "SD", "SD", "PR",
      "PR", "PR", "CR",
      "PD", "SD", "SD",
      "SD", "PR", "PR",
      "CR", "CR", "CR"
    ), levels = c("PD", "SD", "PR", "CR"))
  )

  r_t1 <- sp2_run(
